package com.example.tasks.domain;

import java.time.Instant;
import java.util.Objects;
import java.util.Set;
import java.util.UUID;

/**
 * An assignee's deadline-change proposal (data-model.md, DeadlineRequest). Mirrors the migration:
 * resolution time present exactly when not pending, a cause only when superseded, and an
 * immutable proposal.
 *
 * @param id generated by the database; null until inserted
 */
public record DeadlineRequest(
        Long id,
        Long taskId,
        UUID requesterId,
        Deadline proposed,
        String reason,
        DeadlineRequestState state,
        Instant createdAt,
        Instant resolvedAt,
        UUID resolvedBy,
        String resolutionCause,
        long version) {

    /** Why a pending request was superseded (FR-021, FR-025). */
    public static final String CAUSE_DEADLINE_CHANGED = "deadline_changed";
    public static final String CAUSE_DEADLINE_REMOVED = "deadline_removed";
    public static final String CAUSE_REASSIGNED = "reassigned";
    public static final String CAUSE_COMPLETED = "completed";
    public static final String CAUSE_CANCELLED = "cancelled";

    static final Set<String> CAUSES = Set.of(CAUSE_DEADLINE_CHANGED, CAUSE_DEADLINE_REMOVED, CAUSE_REASSIGNED,
            CAUSE_COMPLETED, CAUSE_CANCELLED);

    public DeadlineRequest {
        Objects.requireNonNull(taskId, "taskId");
        Objects.requireNonNull(requesterId, "requesterId");
        Objects.requireNonNull(proposed, "proposed");
        Objects.requireNonNull(reason, "reason");
        Objects.requireNonNull(state, "state");
        Objects.requireNonNull(createdAt, "createdAt");
        Task.require(Task.isReason(reason), "reason must be 1..2,000 characters");
        Task.require((state == DeadlineRequestState.PENDING) == (resolvedAt == null), "resolved exactly when not pending");
        Task.require(resolutionCause == null || state == DeadlineRequestState.SUPERSEDED, "cause only when superseded");
        Task.require(resolutionCause == null || CAUSES.contains(resolutionCause), "unknown resolution cause");
        Task.require(version > 0, "version must be positive");
    }

    public static DeadlineRequest pending(long taskId, UUID requesterId, Deadline proposed, String reason, Instant at) {
        return new DeadlineRequest(null, taskId, requesterId, proposed, reason, DeadlineRequestState.PENDING, at,
                null, null, null, 1);
    }

    public boolean isPending() {
        return state == DeadlineRequestState.PENDING;
    }

    public DeadlineRequest withId(long newId) {
        return new DeadlineRequest(newId, taskId, requesterId, proposed, reason, state, createdAt, resolvedAt,
                resolvedBy, resolutionCause, version);
    }

    /** The resolved next version of this pending request; {@code cause} is set only for supersession. */
    public DeadlineRequest resolve(DeadlineRequestState newState, UUID by, Instant at, String cause) {
        Task.require(isPending(), "only a pending request can be resolved");
        return new DeadlineRequest(id, taskId, requesterId, proposed, reason, newState, createdAt, at, by, cause,
                version + 1);
    }
}
